package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim by a person on a sheet: an amount (0.00 or more), a date, a note (may be empty)
 * a status (DRAFT to start), a number (given when opened), who opened it and a due (fixed when settled). */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(nullable = false, precision = 19, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(nullable = false)
    private String note;

    @Column(nullable = false)
    private String status = ClaimStatus.DRAFT.name();

    /** The sheet's number given when the claim was opened; null for a draft or a voided claim. */
    @Column(name = "claim_number")
    private Integer number;

    /** The due fixed when the claim was settled; null while it is not settled or its grade had no rate then. */
    @Column(precision = 19, scale = 2)
    private BigDecimal due;

    /** The signed-in name that opened the claim; null while it was never opened. */
    @Column(name = "opened_by")
    private String openedBy;

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return ClaimStatus.valueOf(status);
    }

    public void setStatus(ClaimStatus status) {
        this.status = status.name();
    }

    public Integer getNumber() {
        return number;
    }

    public void setNumber(Integer number) {
        this.number = number;
    }

    public BigDecimal getDue() {
        return due;
    }

    public void setDue(BigDecimal due) {
        this.due = due;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }
}
package net.officefloor.hq.app.claim;

/** A claim as the screen shows it: its amount with two decimals, its date (YYYY-MM-DD) its note, its status, its number (null when it has none)
 * and its due fixed when it was settled (null when it has none), and who opened it (null when never opened). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        Integer number, String due, String openedBy) {

    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().setScale(2).toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getDue() == null ? null : claim.getDue().setScale(2).toPlainString(), claim.getOpenedBy());
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.EntityManager;
import java.math.RoundingMode;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;

/**
 * Moves the claim to the status the action leads to; refuses a change its status does not allow. Opening gives
 * the claim the sheet's next number and records who opened it; voiding clears the number. The one who opened a
 * claim cannot settle it. Settling fixes the claim's due at its person's grade's
 * rate in force on the claim's date (none when no rate applies then, so it stays live). Returns the number the claim had for the audit.
 */
public class ApplyClaimStatus {
    public Integer apply(@PathVariable("action") String action, @Val Claim claim, ClaimRepository repository,
            EntityManager entityManager, PersonRepository people, RateRepository rates,
            @RequestHeader(name = "X-User", required = false) String userHeader) throws ClaimStatusException {
        String user = AuditUser.decode(userHeader);
        if ("open".equals(action) && claim.getStatus().after(action) != null) {
            // Take the number first: it locks the sheet, then re-read the claim so a concurrent open is seen.
            repository.takeNextNumber(claim.getSheetId());
            entityManager.refresh(claim);
            ClaimStatus next = check(claim, action);
            claim.setNumber(repository.lastNumber(claim.getSheetId()));
            claim.setStatus(next);
            claim.setOpenedBy(user);
        } else {
            ClaimStatus next = check(claim, action);
            if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
                throw new ClaimStatusException("The one who opened a claim cannot settle it.");
            }
            claim.setStatus(next);
            if (claim.getStatus() == ClaimStatus.VOID) {
                Integer had = claim.getNumber();
                claim.setNumber(null);
                repository.saveAndFlush(claim);
                return had;
            }
            if (claim.getStatus() == ClaimStatus.SETTLED) {
                claim.setDue(people.findById(claim.getPersonId())
                        .flatMap(p -> rates.findInForce(claim.getSheetId(), p.getGrade(), claim.getDate()))
                        .map(Rate::getPct)
                        .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN))
                        .orElse(null));
            }
        }
        repository.saveAndFlush(claim);
        return claim.getNumber();
    }

    private static ClaimStatus check(Claim claim, String action) throws ClaimStatusException {
        ClaimStatus next = claim.getStatus().after(action);
        if (next == null) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot " + action + ".");
        }
        return next;
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The sheet's claims, newest first. */
    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** Takes the sheet's next claim number; the update locks the sheet's row until the transaction ends, so
     * two claims opened at once are numbered one after the other. */
    @Modifying
    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = :sheetId",
            nativeQuery = true)
    int takeNextNumber(@Param("sheetId") String sheetId);

    @Query(value = "SELECT last_claim_number FROM sheet WHERE id = :sheetId", nativeQuery = true)
    int lastNumber(@Param("sheetId") String sheetId);
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import org.springframework.orm.ObjectOptimisticLockingFailureException;

public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, PersonRepository repository)
            throws InvalidPersonException, PersonConflictException {
        if (request.version() == null || request.version() != person.getVersion()) {
            throw new PersonConflictException();
        }
        if (repository.existsBySheetIdAndNameIgnoreCaseAndIdNot(person.getSheetId(), request.name(), person.getId())) {
            throw new InvalidPersonException("The name is already in use on this sheet.");
        }
        person.setName(request.name());
        person.setGrade(request.grade());
        try {
            repository.saveAndFlush(person);
        } catch (ObjectOptimisticLockingFailureException e) {
            // saved by someone else between the load and this save
            throw new PersonConflictException();
        }
    }
}
