    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        body.set(new PersonRequest(name, grade, request.version()));
    }
}
-- A settled claim's due, fixed when it was settled: its amount times its person's grade's rate then,
-- divided by 100, rounded half up. Null while the claim is not settled, or when the grade had no rate
-- then (its due stays live).
ALTER TABLE claim ADD COLUMN due DECIMAL(19, 2);
-- The version of a person: raised by one on every save. An edit names the version it loaded and
-- is refused when someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
# PUT /api/sheets/{sheetId}/people/{personId} — edit a person. Body: { "name": "...", "grade": "A|B|C", "version": n }.
# Refused with 409 when the person was saved since the editor loaded that version.
